def pages(c):
    S = c["SITE"]; esc = c["esc"]; icon = c["icon"]
    out = []

    SVC = [("Termite inspection", "/termite-inspection-perth"), ("Termite treatment", "/termite-treatment-perth"), ("General pest treatment", "/general-pest-control-perth"),
           ("Ant management", "/ant-control-perth"), ("Rodent management", "/rodent-control-perth"), ("Cockroach management", "/cockroach-control-perth"),
           ("Spider management", "/spider-control-perth"), ("Mosquito management", "/mosquito-control-perth"), ("Vacate flea treatment", "/flea-treatment-perth"),
           ("End-of-lease pest treatment", "/end-of-lease-pest-control-perth"), ("Wasp removal", "/wasp-removal-perth"), ("Bed bug treatment", "/bed-bug-treatment-perth")]
    def svc_cards(sub):
        return ('<ul class="grid grid-3" style="list-style:none;padding:0;margin:0;gap:.5rem">'
            + "".join(f'<li><a href="{u}" style="display:block;padding:.7rem 1rem;border:1px solid var(--line);border-radius:.5rem;text-decoration:none;color:var(--ink)">{esc(n)} {esc(sub)} {icon("arrow", "icon")}</a></li>' for n, u in SVC)
            + '</ul>')

    def investment_note(sub):
        g = next((title for title, _, subs in GROUPS if sub in subs), "")
        if "Coast" in g or "coast" in g:
            why = "Coastal blocks on limestone mean termite management systems are usually drilled and injected rather than trenched, which is the main thing that moves a termite quote here."
        elif "growth corridor" in g or "estates" in g:
            why = "Newer slab-on-ground homes are quicker to treat inside, so general pest jobs tend to sit at the lower end; termite work is quoted on perimeter length and how much of it is paved."
        elif "Stirling" in g or "Inner" in g:
            why = "Older timber-framed homes with roof voids and sub-floors take longer to inspect properly, so termite inspections here are quoted at the full scope rather than a quick look."
        elif "Bayswater" in g:
            why = "Grey sand with a high water table means termite pressure is higher and we quote management systems conservatively; general pest work is unaffected."
        else:
            why = "Most homes here are 1970s to 1980s brick and tile on sand, the standard job for us, so quotes sit close to the middle of each range."
        return (f'<div class="callout"><p><strong>What it typically comes to in {esc(sub)}.</strong> A general pest treatment for a three-bedroom home is $250 to $350, an external ant treatment $250 to $400, a rodent program $220 to $380 and a timber pest inspection $250 to $350. {why} Every job is quoted itemised in writing before we start, with no call-out fee and no deposit. <a href="/pest-control-prices-perth">Full investment guide</a> · <a href="/termite-treatment-cost-perth">{("What termite treatment costs", "Termite treatment cost, worked through", "How a termite quote is built")[sum(map(ord, sub)) % 3]}</a>.</p></div>')

    # ----------------------------------------------------------- suburb pages
    for name, d in SUBURBS.items():
        hero = f"""<section class="hero"><div class="wrap"><div>
  {c['eyebrow'](f"Pest management · {name} WA {d['postcode']} · {d["drive_short"] + (" from our Warwick base" if name != "Warwick" else "")}")}
  <h1>{esc(d['h1'])}</h1>
  <p class="lead">{esc(d['lead'])}</p>
  {c['hours_cue']()}<div class="actions">{c['btn_call']()}{c['btn_quote']()}</div>
  <ul class="trust"><li>Licensed under the WA Pesticides Regs</li><li>In Perth pest management since {S['family_since']}</li><li>Itemised investment in writing</li><li>Same-day for active pests</li></ul>
</div></div></section>"""

        intro = c["section"](
            c["eyebrow"](f"Why {name} gets the pests it gets")
            + '<div class="prose">' + "".join(f"<p>{p}</p>" for p in d["intro"]) + "</div>", "ledger")

        pests = c["section"](
            c["eyebrow"](f"What we treat most in {name}")
            + f'<div class="section-head"><h2>The {name} pest short-list.</h2></div>'
            + '<div class="grid grid-2">' + "".join(c["card"](t, x) for t, x in d["pests"]) + "</div>")

        now = c["section"](
            c["eyebrow"]("What's active now")
            + f'<div class="prose"><h2>This season in {name}.</h2><p>{d["now"]}</p></div>'
            + c["season_strip"](), "ledger")

        services = c["section"](
            c["eyebrow"]("Services") + f'<div class="section-head"><h2>Every service we run in {name}.</h2></div>' + svc_cards(name) + investment_note(name))

        vacate = c["section"](
            c["eyebrow"]("Moving out, or between tenants")
            + f'<div class="prose"><h2>Vacate flea treatment and end-of-lease pest control in {name}.</h2>'
            + f'<p>Moving out of a rental in {name} with a pet? Most WA leases that allowed the pet carry a special condition requiring a professional flea treatment at vacate. We quote from the address within the hour, treat the same week, and email the certificate to you and your agent within the hour of finishing: $150 to $220 by floor area, 30-day re-treatment promise. Book it after the bond clean and carpet clean, just before the keys go back.</p>'
            + '<p><a class="btn btn-ghost" href="/flea-treatment-perth">Vacate flea treatment ' + icon("arrow", "icon") + '</a> <a class="btn btn-ghost" href="/end-of-lease-pest-control-perth">End-of-lease pest control ' + icon("arrow", "icon") + '</a></p></div>', "ledger")

        nb = "".join(c["card"](n, f"Pest management in {esc(n)}, {DRIVE[n]} from Warwick.", slug(n), "Neighbouring suburb", more="See suburb page") for n in d["neighbours"])
        neighbours = c["section"](
            c["eyebrow"]("Nearby")
            + f'<div class="section-head"><h2>Also servicing the suburbs around {name}.</h2><p class="lead">Based in Warwick, {name} is {d["drive"]} away. <a href="/service-areas">All service areas</a>.</p></div>'
            + '<div class="grid grid-3">' + nb + "</div>", "ledger")

        faq_sec = c["section"](c["eyebrow"]("Questions") + f'<div class="section-head"><h2>Asked in {name}.</h2></div>' + c["faq"](d["faqs"]))

        body = hero + intro + pests + now + services + vacate + neighbours + faq_sec + c["quote_block"](f"Get a fair, itemised investment in {name}.")
        out.append({
            "path": slug(name),
            "title": f"Pest Control {name} | Termites, Ants, Rodents, Vacate Flea | DJ Pest",
            "desc": f"Licensed pest control in {name} WA {d['postcode']}, {d['drive']} from our Warwick base. Termite inspections, ants, rodents, general pest and vacate flea treatments. Itemised prices in writing.",
            "body": body,
            "crumbs": [("Service areas", "/service-areas"), (name, None)],
            "schema": [{
                "@type": "Service", "serviceType": f"Pest management in {name}",
                "description": f"Termite inspection, general pest, ant and rodent management for {name} homes and businesses, {d['drive']} from DJ Pest's base in Warwick.",
                "provider": {"@id": S["domain"] + "/#business"},
                "areaServed": {"@type": "City", "name": name, "containedInPlace": {"@type": "AdministrativeArea", "name": "Perth, Western Australia"}},
                "offers": {"@type": "Offer", "priceCurrency": "AUD", "price": 250,
                           "priceSpecification": {"@type": "PriceSpecification", "minPrice": 250, "maxPrice": 5500, "priceCurrency": "AUD"}},
            }, c["faq_schema"](d["faqs"])],
        })

    # -------------------------------------------------------------- hub page
    hub_hero = f"""<section class="hero"><div class="wrap"><div>
  {c['eyebrow']("Service areas · Based in Warwick WA 6024")}
  <h1>Perth's northern suburbs, <em class="red">from the river to Yanchep</em>.</h1>
  <p class="lead">DJ Pest works from a base in Warwick and covers the northern and inner-northern suburbs around it, from Subiaco, Mount Lawley and Bayswater up through Joondalup and Wanneroo to the coast at Yanchep. That keeps response times short, means we know each suburb's soil, housing and pest pressure first-hand, and keeps travel out of your quote.</p>
  {c['hours_cue']()}<div class="actions">{c['btn_call']()}{c['btn_quote']()}</div>
</div></div></section>"""

    why = c["section"](
        c["eyebrow"]("Why not all of Perth")
        + '<div class="grid grid-2" style="align-items:start;gap:3rem"><div class="prose">'
        '<h2>Every suburb, one technician who knows them.</h2>'
        '<p>Most of our work is within fifteen minutes of Warwick. From the depot, Greenwood and Hamersley are five minutes, Duncraig and Balcatta ten, the coast at Sorrento and Hillarys twelve, and Joondalup and Wanneroo fifteen to twenty. The far north, from Clarkson to Yanchep, is on the run sheet but grouped so the drive is not padded into your investment.</p>'
        '<p>The northern suburbs are not one place. The coastal strip sits on Tamala limestone with salt air and a lot of rebuilds. The inland suburbs are yellow Spearwood sand with 1960s to 1980s timber-framed brick homes and mature gardens. The growth corridor north of Joondalup is slab-on-ground estates next to wetland, pine plantation and bush. Termites, coastal brown ants and rodents behave differently in each, and the treatment method changes with the ground. That is easier to get right when the technician has been on the same streets last week.</p>'
        '</div><div class="grid" style="gap:.8rem">'
        + c["card"]("No travel in the quote", "No call-out fee anywhere in the service area. Every job is quoted itemised in writing before we start.")
        + c["card"]("Same-day for active pests", "Rats in the roof, a wasp nest by the door or termites found during a renovation get fast-tracked. Routine treatments are usually within a few days.")
        + c["card"]("Our own technicians", "One of our own licensed technicians attends every job, and the technician who quotes is the one who treats. No subcontracted strangers.")
        + '</div></div>', "ledger")

    groups_html = ""
    for title, blurb, subs in GROUPS:
        lis = "".join(
            (f'<li><a href="{slug(s)}">{esc(s)}</a></li>' if s in SUBURBS else f'<li>{esc(s)}</li>') for s in subs)
        groups_html += f'<div class="card"><div class="num">{esc(title)}</div><h3>{len(subs)} suburbs</h3><p>{esc(blurb)}</p><ul style="columns:2;list-style:none;padding:0;margin:1rem 0 0;line-height:2;font-size:.95rem">{lis}</ul></div>'
    groups = c["section"](
        c["eyebrow"]("Every suburb we cover")
        + '<div class="section-head"><h2>Coast, inland and the growth corridor.</h2><p class="lead">Linked suburbs have their own page with local soil, housing and pest notes. The rest are on the same run and quoted the same way.</p></div>'
        + '<div class="grid grid-3">' + groups_html + '</div>')

    eight = c["section"](
        c["eyebrow"]("Suburb pages")
        + f'<div class="section-head"><h2>{len(SUBURBS)} suburbs, each with its own page.</h2><p class="lead">Soil, housing era, the bush and wetland next door, what is active this season and the questions we get asked there. Pick yours.</p></div>'
        + '<ul style="columns:4;list-style:none;padding:0;margin:0;line-height:2;font-size:.95rem">'
        + "".join(f'<li><a href="{slug(s)}" style="text-decoration:none;color:var(--ink-2)">{esc(s)}</a> <span style="color:var(--ink-3);font-size:.8rem">{esc(DRIVE[s].replace("about ", "").replace(" minutes", " min")) if s != "Warwick" else "base"}</span></li>' for s in sorted(SUBURBS))
        + '</ul>', "ledger")

    rows = [(s, DRIVE[s].capitalize() if s != "Warwick" else "Base", "Yes" if s in SUBURBS else "On request") for s in S["service_area"]]
    drive = c["section"](
        c["eyebrow"]("Drive time from Warwick")
        + '<div class="section-head"><h2>Honest estimates, off-peak.</h2><p class="lead">Add ten minutes in school-run traffic on the freeway or Wanneroo Road. We schedule by area so you get a tight arrival window, not a four-hour one.</p></div>'
        + c["ledger_table"](["Suburb", "Typical drive from Warwick", "Suburb page"], [(esc(a), b, (f'<a href="{slug(a)}">Yes</a>' if cc == "Yes" else cc)) for a, b, cc in rows]))

    hub_faqs = [
        ("Do you service suburbs not on the list?", "The list covers Perth's northern and inner-northern suburbs, from the river up to Yanchep. If you are just outside it, ring and we will tell you straight. We do not take work south of the river or in the hills; the drive would end up in your investment and the service would suffer."),
        ("Is there a travel charge for the far northern suburbs?", "No call-out fee and no travel line on any quote. For Alkimos, Butler, Yanchep and Two Rocks we group bookings by day so the drive is absorbed in scheduling rather than charged to you. It may mean a day or two's wait for a routine job."),
        ("Why does the suburb matter for pest treatment?", "Soil and construction decide the method. A chemical termite management system on the limestone under Sorrento is drilled and injected; on the deep sand under Wanneroo it is trenched. A 1970s Warwick roof with timber framing is proofed differently from a 2015 Joondalup slab home. Knowing the ground saves you money and gets a better result."),
        ("Do you do strata and commercial work across the area?", "Yes: strata common areas, small commercial kitchens, warehouses in the Balcatta and Joondalup industrial precincts, and shopping strip tenancies. Every visit is documented with a treatment record kept for three years as WA regulations require."),
        ("How do I know you are licensed to work in my suburb?", f"Every treatment is carried out by, or under the direct supervision of, a technician holding a WA pest management technician's licence, which applies anywhere in the state. The technician's name and licence number are on your treatment record, and you can ask to see the licence card on the day. {esc(S['reg_line'])}"),
    ]
    hub_faq = c["section"](c["eyebrow"]("Questions") + '<div class="section-head"><h2>About where we work.</h2></div>' + c["faq"](hub_faqs))

    out.insert(0, {
        "path": "/service-areas",
        "title": "Pest Control Service Areas | Perth Northern Suburbs | DJ Pest",
        "desc": "DJ Pest services Perth's northern suburbs from Warwick: Greenwood, Duncraig, Sorrento, Hillarys, Joondalup, Wanneroo, Balcatta, Marangaroo, Stirling and 20 more. Drive times, suburb pages, no call-out fee.",
        "body": hub_hero + why + groups + eight + hub_faq + c["quote_block"]("Get a fair, itemised investment anywhere in the service area."),
        "crumbs": [("Service areas", None)],
        "schema": [c["faq_schema"](hub_faqs), {
            "@type": "Service", "serviceType": "Pest management, Perth northern suburbs",
            "provider": {"@id": S["domain"] + "/#business"},
            "areaServed": [{"@type": "City", "name": s} for s in S["service_area"]],
        }],
    })
    return out
